		findings.push({ code: "the-deterministic-simulation-kernel/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "the-deterministic-simulation-kernel/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

